-- M12: contracts and invoices.
-- * Contracts: generated by the owner from a template; both sides accept in the app (name, time,
--   IP, user agent) through accept_contract. The text is locked once anyone has accepted.
-- * Invoices: per-org number series (atomic), VAT from the published tax rules of the org's
--   country, payments recorded by the server. Off-platform charters can be recorded for invoicing
--   with no commission.
-- * Contract and invoice PDFs live in a private bucket, served only through short signed URLs.

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('business', 'business', false, 10485760, array['application/pdf'])
on conflict (id) do nothing;

create trigger contracts_touch before update on public.contracts for each row execute function private.touch_updated_at();
create trigger invoices_touch before update on public.invoices for each row execute function private.touch_updated_at();
create trigger contract_templates_touch before update on public.contract_templates for each row execute function private.touch_updated_at();
create trigger contracts_audit after insert or update on public.contracts for each row execute function private.write_audit('contract');
create trigger invoices_audit after insert or update or delete on public.invoices for each row execute function private.write_audit('invoice');

-- ---------------------------------------------------------------------------------------------
-- Tax and numbering
-- ---------------------------------------------------------------------------------------------
/** Rate of a tax (e.g. vat) in a country's published rule set; null when there is none. */
create or replace function public.tax_rate_for(p_country text, p_code text) returns integer
language sql stable security definer set search_path = '' as $$
  select t.rate_bps from public.tax_rules t
  join public.compliance_rule_sets s on s.id = t.rule_set_id
  where s.country_code = p_country and s.status = 'published' and t.code = p_code
  order by s.version desc limit 1;
$$;
grant execute on function public.tax_rate_for(text, text) to authenticated;

/** Next invoice number for an org, e.g. INV-2026-0001; restarts each year. */
create or replace function public.next_invoice_number(p_org uuid) returns text
language plpgsql security definer set search_path = '' as $$
declare
  v_year int := extract(year from now())::int;
  s public.invoice_series%rowtype;
begin
  if not public.has_role(p_org, '{owner,manager}') then raise exception 'forbidden'; end if;
  insert into public.invoice_series (org_id, year, next_number) values (p_org, v_year, 1)
  on conflict (org_id) do nothing;
  select * into s from public.invoice_series where org_id = p_org for update;
  if s.year <> v_year then
    s.year := v_year;
    s.next_number := 1;
  end if;
  update public.invoice_series set year = s.year, next_number = s.next_number + 1 where org_id = p_org;
  return s.prefix || '-' || s.year || '-' || lpad(s.next_number::text, 4, '0');
end $$;
revoke execute on function public.next_invoice_number(uuid) from public, anon;
grant execute on function public.next_invoice_number(uuid) to authenticated;

-- ---------------------------------------------------------------------------------------------
-- Contracts
-- ---------------------------------------------------------------------------------------------
create or replace function private.guard_contract() returns trigger
language plpgsql security definer set search_path = '' as $$
declare
  c public.charters%rowtype;
begin
  select * into c from public.charters where id = new.charter_id;
  if not found or c.owner_org_id <> new.owner_org_id or c.charterer_org_id is distinct from new.charterer_org_id then
    raise exception 'invalid_subject';
  end if;
  if tg_op = 'UPDATE' then
    -- Acceptances only via accept_contract; the text is fixed once anyone has accepted.
    if (old.owner_accepted_at is not null or old.charterer_accepted_at is not null)
       and (new.body_html is distinct from old.body_html or new.body_hash is distinct from old.body_hash) then
      raise exception 'contract_locked';
    end if;
    if current_setting('tideline.accepting', true) is distinct from 'on' and (
         new.owner_accepted_at is distinct from old.owner_accepted_at
      or new.charterer_accepted_at is distinct from old.charterer_accepted_at
      or new.acceptance_meta is distinct from old.acceptance_meta) then
      raise exception 'forbidden';
    end if;
  end if;
  return new;
end $$;
create trigger contracts_guard before insert or update on public.contracts
  for each row execute function private.guard_contract();

/** One side accepts the contract text as it stands (name typed, IP and user agent recorded). */
create or replace function public.accept_contract(p_contract uuid, p_name text, p_ip text, p_user_agent text)
returns text language plpgsql security definer set search_path = '' as $$
declare
  k public.contracts%rowtype;
  v_side text;
begin
  select * into k from public.contracts where id = p_contract for update;
  if not found then raise exception 'not_found'; end if;
  if length(trim(coalesce(p_name, ''))) < 2 then raise exception 'validation'; end if;
  if public.has_role(k.owner_org_id, '{owner}') then v_side := 'owner';
  elsif k.charterer_org_id is not null and public.has_role(k.charterer_org_id, '{owner,manager,charterer}') then v_side := 'charterer';
  else raise exception 'forbidden';
  end if;
  perform set_config('tideline.accepting', 'on', true);
  if v_side = 'owner' then
    if k.owner_accepted_at is not null then raise exception 'already_decided'; end if;
    update public.contracts set owner_accepted_by = (select auth.uid()), owner_accepted_at = now(),
      acceptance_meta = acceptance_meta || jsonb_build_object('owner', jsonb_build_object('name', trim(p_name), 'ip', p_ip, 'user_agent', left(p_user_agent, 300), 'body_hash', k.body_hash))
    where id = k.id;
  else
    if k.charterer_accepted_at is not null then raise exception 'already_decided'; end if;
    update public.contracts set charterer_accepted_by = (select auth.uid()), charterer_accepted_at = now(),
      acceptance_meta = acceptance_meta || jsonb_build_object('charterer', jsonb_build_object('name', trim(p_name), 'ip', p_ip, 'user_agent', left(p_user_agent, 300), 'body_hash', k.body_hash))
    where id = k.id;
  end if;
  perform set_config('tideline.accepting', 'off', true);
  -- Both sides signed: the charter moves on to payment (escrow, M13).
  update public.charters set status = 'pending_payment'
   where id = k.charter_id and status = 'pending_contract'
     and exists (select 1 from public.contracts where id = k.id and owner_accepted_at is not null and charterer_accepted_at is not null);
  return v_side;
end $$;
revoke execute on function public.accept_contract(uuid, text, text, text) from public, anon;
grant execute on function public.accept_contract(uuid, text, text, text) to authenticated;

-- A default template (plain English; owners can add their own).
insert into public.contract_templates (org_id, country_code, locale, name, body_template, variables) values (
  null, null, 'en', 'Standard time charter (short form)',
  E'TIME CHARTER AGREEMENT\n\nBetween {{owner_name}} ("the Owner") and {{charterer_name}} ("the Charterer").\n\n1. Vessel. The Owner lets the vessel {{vessel_name}} ({{vessel_type}}) to the Charterer.\n2. Period. From {{start_date}} to {{end_date}} ({{days}} days), at {{location}}.\n3. Hire. {{day_rate}} per day, plus a mobilisation fee of {{mobilisation}}. Estimated total {{total_value}}.\n4. Fuel. {{fuel_terms}}\n5. Payment. {{payment_terms}}\n6. Crew. The Owner provides a competent crew and keeps the vessel''s certificates valid for the period.\n7. Safety. The master may refuse any voyage he or she judges unsafe.\n8. Law. This agreement is governed by the laws of {{governing_country}}.\n\nAccepted in Tideline by both parties; names, times and IP addresses are recorded below.',
  '["owner_name","charterer_name","vessel_name","vessel_type","start_date","end_date","days","location","day_rate","mobilisation","total_value","fuel_terms","payment_terms","governing_country"]'
);

-- ---------------------------------------------------------------------------------------------
-- Off-platform charters (invoicing only, no commission)
-- ---------------------------------------------------------------------------------------------
create or replace function private.guard_offplatform_charter() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if not new.booked_on_platform then
    new.commission_bps := 0;
    new.charterer_org_id := null;
    new.status := 'active';
    if coalesce(trim(new.client_name), '') = '' then raise exception 'validation'; end if;
  end if;
  if not exists (select 1 from public.vessels where id = new.vessel_id and org_id = new.owner_org_id) then
    raise exception 'invalid_subject';
  end if;
  return new;
end $$;
create trigger charters_guard before insert on public.charters
  for each row execute function private.guard_offplatform_charter();

-- ---------------------------------------------------------------------------------------------
-- RLS
-- ---------------------------------------------------------------------------------------------
alter table public.contract_templates enable row level security;
alter table public.contracts enable row level security;
alter table public.invoices enable row level security;
alter table public.invoice_series enable row level security;
revoke all on public.contract_templates, public.contracts, public.invoices, public.invoice_series from anon;
revoke all on public.invoice_series from authenticated;

create policy templates_select on public.contract_templates for select to authenticated
  using (org_id is null or public.has_role(org_id));
create policy templates_write on public.contract_templates for all to authenticated
  using (org_id is not null and public.has_role(org_id, '{owner,manager}'))
  with check (org_id is not null and public.has_role(org_id, '{owner,manager}'));

create policy contracts_select on public.contracts for select to authenticated
  using (public.has_role(owner_org_id) or (charterer_org_id is not null and public.has_role(charterer_org_id)));
create policy contracts_insert on public.contracts for insert to authenticated
  with check (public.has_role(owner_org_id, '{owner,manager}'));
create policy contracts_update on public.contracts for update to authenticated
  using (public.has_role(owner_org_id, '{owner,manager}')) with check (public.has_role(owner_org_id, '{owner,manager}'));
revoke delete on public.contracts from authenticated;

-- Owners record off-platform charters; everything else about charters goes through functions.
grant insert on public.charters to authenticated;
create policy charters_insert_offplatform on public.charters for insert to authenticated
  with check (not booked_on_platform and public.has_role(owner_org_id, '{owner,manager}'));

-- Invoices: the issuing org's owners and managers; the billed charterer org can read theirs.
create policy invoices_select on public.invoices for select to authenticated
  using (public.has_role(org_id, '{owner,manager}')
         or ((bill_to ->> 'org_id') is not null and public.has_role((bill_to ->> 'org_id')::uuid)));
create policy invoices_write on public.invoices for all to authenticated
  using (public.has_role(org_id, '{owner,manager}')) with check (public.has_role(org_id, '{owner,manager}'));
-- Paid amounts and reminder times are set only by the server (payments, the overdue job): a
-- column-level revoke doesn't override a table-wide grant, so grant the editable columns instead.
revoke update on public.invoices from authenticated;
grant update (bill_to, line_items, currency, locale, subtotal_minor, discount_minor, tax_minor, tax_rule_code,
              tax_rate_bps, total_minor, issue_date, due_date, status, pdf_path, payment_link, sent_at, notes,
              updated_at) on public.invoices to authenticated;

-- ---------------------------------------------------------------------------------------------
-- Overdue invoices: daily 07:15 UTC through the app's job endpoint.
-- ---------------------------------------------------------------------------------------------
select cron.schedule('invoices-overdue', '15 7 * * *', $$select private.run_job('invoices-overdue')$$);
